import{_ as t,o as i,c as a,a2 as r}from"./chunks/framework.XaTYfhfj.js";const u=JSON.parse('{"title":"Project Pitch: TruthGuard Platform","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),n={name:"00b-project-pitch.md"};function o(s,e,c,d,h,l){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="project-pitch-truthguard-platform" tabindex="-1">Project Pitch: TruthGuard Platform <a class="header-anchor" href="#project-pitch-truthguard-platform" aria-label="Permalink to &quot;Project Pitch: TruthGuard Platform&quot;">​</a></h1><h2 id="_1-the-30-second-elevator-pitch" tabindex="-1">1. The 30-Second Elevator Pitch <a class="header-anchor" href="#_1-the-30-second-elevator-pitch" aria-label="Permalink to &quot;1. The 30-Second Elevator Pitch&quot;">​</a></h2><p><em>(Perfect for the opening question: &quot;Tell me about your project in 30 seconds.&quot;)</em></p><blockquote><p>&quot;I built TruthGuard, an integrated cyber-defense and digital media forensics platform designed to detect generative AI deepfakes, surveillance camera tampering, and voice phishing scams.</p><p>Rather than relying on a single static check, I architected a federated micro-frontend suite connecting five specialized engines—combining client-side EXIF metadata parsing and Web Crypto SHA-256 hashing with serverless edge AI functions for multi-modal verification.</p><p>The platform unifies image error level analysis, telecommunication scam triage, and cryptographic asset provenance into an NVIDIA-inspired dark workstation.</p><p>It solves the growing crisis of synthetic media by giving security analysts instant, multi-layered evidence verification with definitive confidence scores.&quot;</p></blockquote><hr><h2 id="_2-the-2-minute-comprehensive-pitch" tabindex="-1">2. The 2-Minute Comprehensive Pitch <a class="header-anchor" href="#_2-the-2-minute-comprehensive-pitch" aria-label="Permalink to &quot;2. The 2-Minute Comprehensive Pitch&quot;">​</a></h2><p><em>(Tailored for: &quot;Walk me through what you built, why you built it, and the architecture.&quot;)</em></p><blockquote><p>&quot;With the recent explosion of generative AI—such as diffusion image generators, ElevenLabs voice cloning, and automated phishing bots—traditional security perimeters are completely blind to synthetic media. Bad actors can now bypass biometric gates, spoof executive phone calls, and tamper with physical CCTV feeds. I built TruthGuard to give security teams and journalists a single, unified forensics workstation to detect and mitigate these multi-modal threats in real time.</p><p>Architecturally, TruthGuard is structured as a federated micro-frontend platform. At its core is a central Hub built with React 18, TypeScript, and Vite. The Hub coordinates five specialized forensic engines:</p><p>First, <strong>TruthLence</strong>, which inspects uploaded imagery, documents, and news URLs for generative compression artifacts, cross-referencing claims against established fact-checking sources through Supabase Edge Functions.</p><p>Second, <strong>DEEP SCAN</strong>, an optical tamper and camera forensics engine. It processes media right in the browser using the Web Crypto API to calculate SHA-256 hashes and <code>exifr</code> to extract detailed camera metadata, GPS coordinates, and detect whether editing software like Photoshop, GIMP, or Canva altered the image.</p><p>Third, <strong>DeepGuard</strong>, which triages telecommunication threats. It analyzes phone call transcripts and SMS messages for voice synthesis patterns, artificial urgency, and smishing attacks.</p><p>Fourth, <strong>MediaVault</strong>, a cryptographic asset custody drive built with Zustand that handles file ingestion, simulated multi-stage encryption, and immutable activity audit logging.</p><p>And fifth, the <strong>VeritAI Executive Dashboard</strong>, a 1,600-line analytical command center featuring radial confidence gauges, source reliability tiers based on Media Bias/Fact Check standards, and emotional sensationalism meters.</p><p>One engineering highlight I&#39;m proud of is our client-side dynamic port prober in <code>FeatureEmbed.tsx</code>. It actively probes localhost ports using non-blocking HEAD requests to discover running micro-frontend instances dynamically without requiring a hardcoded backend registry.</p><p>Overall, TruthGuard combines client-side cryptographic speed with serverless AI intelligence to provide deep, explainable, and trustworthy forensics against modern synthetic threats.&quot;</p></blockquote>',8)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
